begin;
create temporary table gallery_test_context as select (select id from profiles where username='neorai18') uid,gen_random_uuid() other_uid,gen_random_uuid() album_id,gen_random_uuid() public_id,(select id from matches limit 1) match_id;
grant select on gallery_test_context to authenticated,anon;
insert into fan_album_photos(id,user_id,match_id,storage_path,caption) select album_id,uid,match_id,uid||'/'||match_id||'/rollback-gallery.jpg','rollback-only-private-photo' from gallery_test_context;
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',uid)::text,true) from gallery_test_context;
set local role authenticated;
do $$declare p fan_public_photos;c record;begin select * into c from gallery_test_context;p:=request_public_photo(c.album_id,null,'rollback-public-caption');if p.status<>'pending' or p.user_id<>c.uid then raise exception 'Upload allocated incorrectly';end if;
 begin update fan_public_photos set status='approved' where id=p.id;raise exception 'Client directly approved';exception when insufficient_privilege then null;end;
end$$;
reset role;
update gallery_test_context set public_id=(select id from fan_public_photos where album_photo_id=gallery_test_context.album_id);
insert into storage.objects(bucket_id,name,owner_id) select 'fan-public-albums',storage_path,user_id::text from fan_public_photos where id=(select public_id from gallery_test_context);
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',other_uid)::text,true) from gallery_test_context;
set local role authenticated;
do $$declare c record;begin select * into c from gallery_test_context;if exists(select 1 from fan_public_photos where id=c.public_id) then raise exception 'Pending photo exposed';end if;if exists(select 1 from fan_album_photos where id=c.album_id) then raise exception 'Private original exposed';end if;
 begin perform request_public_photo(c.album_id,null,'');raise exception 'Other private photo published';exception when raise_exception then if sqlerrm<>'Private album unavailable' then raise;end if;end;
 begin perform review_public_photo(c.public_id,'approved');raise exception 'Non-owner approved';exception when raise_exception then if sqlerrm<>'Forbidden' then raise;end if;end;
end$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',uid)::text,true) from gallery_test_context;
set local role authenticated;
select review_public_photo(public_id,'approved') from gallery_test_context;
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
do $$declare c record;begin select * into c from gallery_test_context;if not exists(select 1 from fan_public_photos where id=c.public_id) then raise exception 'Approved photo hidden';end if;if not exists(select 1 from storage.objects where bucket_id='fan-public-albums' and name=(select storage_path from fan_public_photos where id=c.public_id)) then raise exception 'Approved image inaccessible';end if;end$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',uid)::text,true) from gallery_test_context;
set local role authenticated;
select withdraw_public_photo(public_id) from gallery_test_context;
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
do $$begin if exists(select 1 from fan_public_photos where id=(select public_id from gallery_test_context)) then raise exception 'Withdrawn photo remains public';end if;if exists(select 1 from storage.objects where bucket_id='fan-public-albums' and owner_id=(select uid::text from gallery_test_context)) then raise exception 'Withdrawn image remains public';end if;end$$;
reset role;
rollback;
select jsonb_build_object('passed',true,'rolled_back',true,'uploaded_real_photos',false,'checks',jsonb_build_array('private default','pending isolation','other original inaccessible','client cannot approve','Owner approval only','approved metadata visible','approved storage visible','withdrawn metadata private','withdrawn storage private')) as result;
